            visited.add((r, 0))
            q.append((r, 0))
        if grid[r][cols-1] == bg_val:
            visited.add((r, cols-1))
            q.append((r, cols-1))

    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    while q:
        r, c = q.popleft()
        for dr, dc in directions:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited and grid[nr][nc] == bg_val:
